{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    if not segments:
        raise ValueError('No segments')
    total_min = sum(s['minimum'] for s in segments)
    total_cap = sum(s['capacity'] for s in segments)
    if budget < total_min or budget > total_cap:
        raise ValueError('Budget out of feasible range')
    alloc = [s['minimum'] for s in segments]
    remaining = budget - total_min
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, s in enumerate(segments):
            if alloc[i] >= s['capacity']:
                continue
            score = s['importance'] / (alloc[i] + 1)
            if score > best_score:
                best_score = score
                best_idx = i
        if best_idx == -1:
            break
        alloc[best_idx] += 1
        remaining -= 1
    by_name = {s['name']: alloc[i] for i, s in enumerate(segments)}
    total = sum(alloc)
    return {'allocations': alloc, 'by_name': by_name, 'total': total}"
}
